package net.fodoth.skina.neoguanniao.network;
import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; import net.minecraft.resources.ResourceLocation; import net.minecraft.server.level.ServerPlayer; import net.neoforged.neoforge.network.handling.IPayloadContext; import org.jetbrains.annotations.NotNull; import java.util.UUID;
public record FinishPhotoUploadPacket(UUID uploadId) implements CustomPacketPayload { public static final Type<FinishPhotoUploadPacket> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath("neoguanniao","finish_photo_upload")); public static final StreamCodec<RegistryFriendlyByteBuf,FinishPhotoUploadPacket> STREAM_CODEC=StreamCodec.of((b,p)->b.writeUUID(p.uploadId),b->new FinishPhotoUploadPacket(b.readUUID())); public static void handle(FinishPhotoUploadPacket p,IPayloadContext c){c.enqueueWork(()->{if(c.player() instanceof ServerPlayer s)PhotoUploadManager.finish(s,p.uploadId);});} @Override public @NotNull Type<? extends CustomPacketPayload> type(){return TYPE;} }
